","import React from 'react';
import './ExecHealthScore.css';

export default function ExecHealthScore({ data }: { data?: { score: number; summaryPoints: string[] } }) {
  const score = data?.score ?? 0;
  const summaryPoints = data?.summaryPoints ?? [];
  const circumference = 2 * Math.PI * 45;
  const offset = circumference - (score / 100) * circumference;

  return (
    <div className="exec-card exec-health-score">
      <div className="exec-section-title">Enterprise PulseScore</div>
      <div className="exec-health-score__gauge">
        <svg width="180" height="180" viewBox="0 0 100 100">
          <circle className="exec-health-score__gauge-bg" cx="50" cy="50" r="45" />
          <circle
            className="exec-health-score__gauge-fill"
            cx="50" cy="50" r="45"
            strokeDasharray={circumference}
            strokeDashoffset={offset}
          />
        </svg>
        <div className="exec-health-score__gauge-text">
          <div className="exec-health-score__score">{score}</div>
          <div className="exec-health-score__label">PulseScore</div>
        </div>
      </div>
      <div className="exec-health-score__status">
        <span className="exec-health-score__status-text">✦ {score >= 90 ? 'Excellent' : score >= 75 ? 'Good' : 'Needs Attention'}</span>
      </div>
      <div className="exec-health-score__improvement">
        ↑ +5 improvement this week
      </div>
      <div className="exec-health-score__summary">
        <div className="exec-health-score__summary-title">AI Executive Summary</div>
        <ul className="exec-health-score__summary-list">
          {summaryPoints.map((point, i) => (
            <li key={i} className="exec-health-score__summary-item">{point}</li>
          ))}
        </ul>
      </div>
    </div>
  );
}
