export default function ExecGrowthChart({ data }: { data?: { revenuePoints: string; ordersPoints: string; profitPoints: string } }) {
  const revenuePoints = data?.revenuePoints ?? '';
  const ordersPoints = data?.ordersPoints ?? '';
  const profitPoints = data?.profitPoints ?? '';

  return (
    <div className="exec-card exec-growth-chart">
      <div className="exec-section-title">30-Day Growth Trajectory</div>
      <div className="exec-growth-chart__legend">
        <div className="exec-growth-chart__legend-item">
          <span className="exec-growth-chart__legend-dot" style={{ background: '#00c896' }}></span>
          Revenue
        </div>
        <div className="exec-growth-chart__legend-item">
          <span className="exec-growth-chart__legend-dot" style={{ background: '#3b82f6' }}></span>
          Orders
        </div>
        <div className="exec-growth-chart__legend-item">
          <span className="exec-growth-chart__legend-dot" style={{ background: '#8b5cf6' }}></span>
          Profit
        </div>
      </div>
      <svg className="exec-growth-chart__svg" viewBox="0 0 620 200" preserveAspectRatio="none">
        {/* Grid lines */}
        <line className="exec-growth-chart__grid-line" x1="20" y1="50" x2="600" y2="50" />
        <line className="exec-growth-chart__grid-line" x1="20" y1="100" x2="600" y2="100" />
        <line className="exec-growth-chart__grid-line" x1="20" y1="150" x2="600" y2="150" />
        {/* Weekend highlights */}
        <rect className="exec-growth-chart__weekend" x="100" y="20" width="40" height="170" />
        <rect className="exec-growth-chart__weekend" x="240" y="20" width="40" height="170" />
        <rect className="exec-growth-chart__weekend" x="380" y="20" width="40" height="170" />
        <rect className="exec-growth-chart__weekend" x="520" y="20" width="40" height="170" />
        {/* Campaign spike highlight */}
        <rect x="440" y="20" width="30" height="170" fill="rgba(245, 158, 11, 0.06)" />
        {/* Lines */}
        <polyline className="exec-growth-chart__line" points={revenuePoints} stroke="#00c896" />
        <polyline className="exec-growth-chart__line" points={ordersPoints} stroke="#3b82f6" />
        <polyline className="exec-growth-chart__line" points={profitPoints} stroke="#8b5cf6" />
        {/* X-axis labels */}
        <text className="exec-growth-chart__label" x="20" y="195">Day 1</text>
        <text className="exec-growth-chart__label" x="150" y="195">Week 1</text>
        <text className="exec-growth-chart__label" x="300" y="195">Week 2</text>
        <text className="exec-growth-chart__label" x="450" y="195">Week 3</text>
        <text className="exec-growth-chart__label" x="570" y="195">Day 30</text>
      </svg>
    </div>
  );
}
