","import React from 'react';
import './ExecFinancial.css';

interface FinData {
  label: string;
  value: string;
  pct: number;
  color: string;
}

function DonutChart({ data }: { data: FinData[] }) {
  let offset = 0;
  const radius = 35;
  const circumference = 2 * Math.PI * radius;

  return (
    <svg className="exec-financial__donut-svg" viewBox="0 0 100 100">
      {data.map((item) => {
        const dash = (item.pct / 100) * circumference;
        const currentOffset = offset;
        offset += dash;
        return (
          <circle
            key={item.label}
            cx="50" cy="50" r={radius}
            fill="none"
            stroke={item.color}
            strokeWidth="12"
            strokeDasharray={`${dash} ${circumference - dash}`}
            strokeDashoffset={-currentOffset}
            transform="rotate(-90 50 50)"
          />
        );
      })}
    </svg>
  );
}

export default function ExecFinancial({ data }: { data?: { revenue: FinData[]; expenses: FinData[] } }) {
  const revenue = data?.revenue ?? [];
  const expenses = data?.expenses ?? [];

  return (
    <div className="exec-card exec-financial">
      <div className="exec-section-title">Financial Breakdown</div>
      <div className="exec-financial__columns">
        <div>
          <div className="exec-financial__column-title">Revenue Sources</div>
          <div className="exec-financial__donut">
            <DonutChart data={revenue} />
            <div className="exec-financial__donut-items">
              {revenue.map((r) => (
                <div key={r.label} className="exec-financial__donut-item">
                  <span className="exec-financial__donut-dot" style={{ background: r.color }}></span>
                  {r.label}
                  <span className="exec-financial__donut-value">{r.value}</span>
                </div>
              ))}
            </div>
          </div>
        </div>
        <div>
          <div className="exec-financial__column-title">Expense Breakdown</div>
          <div className="exec-financial__donut">
            <DonutChart data={expenses} />
            <div className="exec-financial__donut-items">
              {expenses.map((e) => (
                <div key={e.label} className="exec-financial__donut-item">
                  <span className="exec-financial__donut-dot" style={{ background: e.color }}></span>
                  {e.label}
                  <span className="exec-financial__donut-value">{e.value}</span>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
